from itertools import permutations

def calculate_sum(n):
    S = list(permutations(range(1, n + 1)))
    total_sum = 0

    for p in S:
        # Calculate sigma(pi) - parity
        inversions = 0
        p_list = list(p)
        for i in range(n):
            for j in range(i + 1, n):
                if p_list[i] > p_list[j]:
                    inversions += 1

        if inversions % 2 == 0:
            sigma = 1  # Even permutation
        else:
            sigma = -1 # Odd permutation

        # Calculate v(pi) - fixed points
        fixed_points = 0
        for i in range(n):
            # Note: indices are 0 to n-1, values are 1 to n
            if p[i] == i + 1:
                fixed_points += 1

        # Calculate term
        term = sigma / (fixed_points + 1)
        total_sum += term

    return total_sum

# Test for n=3
n3_sum = calculate_sum(3)
print(f"Sum for n=3: {n3_sum}")
